<script setup>
import { computed, ref, watch } from 'vue';
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import Layout from '@/Layouts/ProviderLayout.vue';
import AccountPageHeader from '@/Components/Account/AccountPageHeader.vue';
const props=defineProps({service:String,status:String,application:Object,requirements:{type:Object,default:()=>({})}});
const titles={spaces:'Aadi Properties verification',haul:'Aadi UV verification',raketeer:'Aadi Raket verification'};
const user=usePage().props.auth.user;
const editing=ref(false), selectionError=ref('');
const form=useForm({version:props.application?.version||null,action:'submit',displayName:props.application?.displayName||user.name,phone:props.application?.phone||'',area:props.application?.area||'',description:props.application?.description||'',details:{applicantType:'individual',businessName:'',relationship:'',serviceCategory:'',skills:'',experienceYears:'',...props.application?.details},documents:[],documentMeta:[],keepDocuments:(props.application?.documents||[]).map(doc=>doc.index),confirmed:false});
const pending=computed(()=>props.application?.status==='pending' && props.status==='pending');
const locked=computed(()=>pending.value || (props.status==='approved'&&!editing.value));
const savedDocuments=computed(()=>(props.application?.documents||[]).filter(doc=>form.keepDocuments.includes(doc.index)));
const providedTypes=computed(()=>new Set([...savedDocuments.value.map(doc=>doc.type),...form.documentMeta.map(doc=>doc.type)]));
const missingRequired=computed(()=>Object.entries(props.requirements).filter(([type,rule])=>rule.required&&!providedTypes.value.has(type)));
const label=type=>props.requirements[type]?.label||'Supporting document';
function choose(event){const files=Array.from(event.target.files||[]);event.target.value='';selectionError.value='';if(files.length+form.documents.length+savedDocuments.value.length>10||files.some(f=>f.size>5*1024*1024||!['image/jpeg','image/png','image/webp','application/pdf'].includes(f.type))){selectionError.value='Use JPG, PNG, WebP, or PDF files up to 5 MB each, with at most 10 documents in total.';return;}for(const file of files){form.documents.push(file);form.documentMeta.push({type:'',reference:'',expiresAt:''});}}
function removeNew(index){form.documents.splice(index,1);form.documentMeta.splice(index,1);}
function submit(action='submit'){if(form.processing)return;form.action=action;form.post(`/provider-applications/${props.service}`,{forceFormData:true,preserveScroll:true,onSuccess:()=>{editing.value=false;form.documents=[];form.documentMeta=[];form.confirmed=false;}});}
watch(()=>props.application,app=>{form.version=app?.version||null;form.keepDocuments=(app?.documents||[]).map(doc=>doc.index);form.displayName=app?.displayName||user.name;form.phone=app?.phone||'';form.area=app?.area||'';form.description=app?.description||'';form.details={applicantType:'individual',businessName:'',relationship:'',serviceCategory:'',skills:'',experienceYears:'',...app?.details};});
</script>
<template><Layout><Head :title="titles[service]"/><main class="account-page verification-page"><Link href="/become-provider" class="text-button">← All provider roles</Link><AccountPageHeader :title="titles[service]" description="Complete your provider profile and submit private documents for review."/>
<div v-if="application?.reviewNote" class="notice" role="status"><strong>Admin feedback</strong><p>{{ application.reviewNote }}</p></div>
<section v-if="locked" class="form-section"><span class="availability-tag" :class="status==='approved'?'active':'draft'">{{ status==='approved'?'Role approved':'Under review' }}</span><h2>{{ pending?'Your application is being reviewed.':'Your provider role is approved.' }}</h2><p>Approval applies to this provider role. It is not a guarantee of an individual listing’s ownership, condition, or availability.</p><div class="actions"><Link v-if="status==='approved'" :href="`/my-listings/${service}/new`" class="button primary">Create listing</Link><button v-if="status==='approved'" class="button" type="button" @click="editing=true">Update verification</button></div><dl><dt>Display / business name</dt><dd>{{ application?.displayName }}</dd><dt>Contact phone</dt><dd>{{ application?.phone }}</dd><dt>Service area</dt><dd>{{ application?.area }}</dd><dt>About your offering</dt><dd>{{ application?.description }}</dd></dl><dl><template v-for="(value,key) in application?.details" :key="key"><template v-if="value !== null && value !== ''"><dt>{{ {applicantType:'Applicant type',businessName:'Business name',relationship:'Ownership / authority',serviceCategory:'Service category',skills:'Skills and qualifications',experienceYears:'Years of experience'}[key] || key }}</dt><dd>{{ value }}</dd></template></template></dl><ul class="verification-files"><li v-for="doc in application?.documents||[]" :key="doc.url"><a :href="doc.url" target="_blank" rel="noopener">{{ label(doc.type) }} · {{ doc.name }}</a><small v-if="doc.reference">{{ doc.reference }}</small><small v-if="doc.expiresAt">Expires {{ doc.expiresAt }}</small></li></ul></section>
<form v-else class="application-form" @submit.prevent="submit()"><fieldset :disabled="form.processing">
<div v-if="application?.status==='draft'" class="notice" role="status">Draft saved. Submit when your documents are ready.</div>
<div v-if="status==='approved'" class="notice">Submitting updated verification sends this role back for review. Listing tools will be unavailable until approved again.</div>
<div v-if="Object.keys(form.errors).length" class="notice error" role="alert"><p v-for="(error,key) in form.errors" :key="key">{{ error }}</p></div>
<section class="form-section"><h2>Provider profile</h2><div class="field-row"><label>Applying as<select v-model="form.details.applicantType"><option value="individual">Individual</option><option value="business">Business</option></select></label><label>Display name<input v-model="form.displayName" maxlength="255" required/></label></div><label v-if="form.details.applicantType==='business'">Registered business name<input v-model="form.details.businessName" maxlength="255" required/></label><div class="field-row"><label>Contact phone<input v-model="form.phone" type="tel" autocomplete="tel" maxlength="40" required/></label><label>City / service area<input v-model="form.area" maxlength="255" required/></label></div>
<label v-if="service!=='raketeer'">{{ service==='haul'?'Relationship to registered vehicle owner':'Relationship to property' }}<input v-model="form.details.relationship" maxlength="255" placeholder="Owner, authorized representative, or other relationship"/></label>
<template v-else><div class="field-row"><label>Service category<input v-model="form.details.serviceCategory" maxlength="255" placeholder="e.g. Electrical work, tutoring, design"/></label><label>Years of experience<input v-model="form.details.experienceYears" type="number" min="0" max="80"/></label></div><label>Skills and qualifications<textarea v-model="form.details.skills" rows="3" maxlength="1000"/></label></template><label>About your offering<textarea v-model="form.description" rows="4" maxlength="3000" minlength="20" required/></label></section>
<section class="form-section"><h2>Verification documents</h2><p>These documents are private. Only you and authorized administrators can download them. Do not upload these files to your public photo gallery.</p><ul class="verification-requirements"><li v-for="(rule,type) in requirements" :key="type"><span>{{ rule.label }}</span><strong :class="{provided:providedTypes.has(type)}">{{ providedTypes.has(type)?'Added':rule.required?'Required':'Optional / if applicable' }}</strong></li></ul>
<ul class="verification-files"><li v-for="doc in savedDocuments" :key="doc.index"><a :href="doc.url" target="_blank" rel="noopener">{{ label(doc.type) }} · {{ doc.name }}</a><small v-if="doc.reference">{{ doc.reference }}</small><small v-if="doc.expiresAt">Expires {{ doc.expiresAt }}</small><button type="button" class="text-button" :disabled="form.processing" @click="form.keepDocuments=form.keepDocuments.filter(i=>i!==doc.index)">Remove {{ doc.name }}</button></li></ul>
<label>Add documents<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple :disabled="form.processing" @change="choose"/></label><p>Up to 10 files total, 5 MB per file. Saved documents are retained unless you remove them.</p><p v-if="selectionError" class="error" role="alert">{{ selectionError }}</p>
<div v-for="(file,index) in form.documents" :key="index" class="verification-upload"><strong>{{ file.name }}</strong><label>Document type<select v-model="form.documentMeta[index].type" aria-label="Document type" required><option value="" disabled>Select document type</option><option v-for="(rule,type) in requirements" :key="type" :value="type">{{ rule.label }}</option></select></label><label>Property, vehicle, or qualification reference<input v-model="form.documentMeta[index].reference" maxlength="255" placeholder="e.g. Vehicle plate or property address (private)"/></label><label>Expiry date (only if shown on document)<input v-model="form.documentMeta[index].expiresAt" type="date"/></label><button type="button" class="text-button" :disabled="form.processing" @click="removeNew(index)">Remove {{ file.name }}</button></div>
<p v-if="missingRequired.length" class="document-progress" role="status">{{ missingRequired.length }} required document {{ missingRequired.length===1?'type still needed':'types still needed' }}. You can save a draft and return later.</p><label class="confirmation"><input v-model="form.confirmed" type="checkbox" required/><span>I confirm these details and documents are accurate and authorize Aadi administrators to review this application.</span></label><p v-if="form.progress" role="status">Uploading: {{ form.progress.percentage }}%</p><div class="actions"><button type="submit" class="button primary" :disabled="form.processing">{{ form.processing?'Saving…':'Submit for review' }}</button><button v-if="status!=='approved'" type="button" class="button" :disabled="form.processing" @click="submit('draft')">Save draft</button></div></section>
</fieldset></form></main></Layout></template>
<style scoped>
.verification-page fieldset{border:0;padding:0;margin:0;min-width:0}.verification-requirements li{display:flex;justify-content:space-between;gap:14px;padding:10px 0;border-bottom:1px solid #dce7e4}.verification-requirements .provided{color:#137671;background:#e3f6f4;padding:0 8px;border-radius:6px}.document-progress{padding:12px;background:#fff3bf;border-radius:10px}.verification-page { max-width:1000px!important; }.verification-page>.account-page-heading{margin-top:24px;}.verification-files{list-style:none;padding:0;}.verification-files li,.verification-upload{border:1px solid var(--line);border-radius:10px;padding:16px;margin:16px 0;overflow-wrap:anywhere;}.verification-files a{color:#137671;text-decoration:underline;}.verification-files small{display:block;margin:6px 0;}.verification-files button{display:block;min-height:44px;}.verification-upload{display:grid;gap:12px;}.verification-requirements{padding-left:20px;font-size:13px;line-height:1.8;}.verification-requirements strong,.verification-requirements span{margin-left:8px;font-size:11px;color:#137671;}.verification-page dt{font-weight:700;margin-top:16px;}.verification-page dd{margin:6px 0;}.verification-page p{color:var(--muted);}.verification-page .confirmation{display:flex;flex-direction:row;align-items:flex-start;gap:12px;margin:20px 0;}.verification-page .confirmation input{width:20px;min-height:20px;flex:none;}
</style>
